import re

def cmp_semver(a, b):
    def parse_version(v):
        # Split version from build metadata (ignored)
        main_part = v.split('+', 1)[0]

        # Separate core version from pre-release
        if '-' in main_part:
            core, prerelease = main_part.split('-', 1)
            prerelease_parts = prerelease.split('.')
        else:
            core = main_part
            prerelease_parts = None

        # Parse major, minor, patch
        major, minor, patch = map(int, core.split('.'))

        # Process pre-release identifiers for comparison
        processed_prerelease = []
        if prerelease_parts is not None:
            for part in prerelease_parts:
                if part.isdigit():
                    processed_prerelease.append((0, int(part)))
                else:
                    processed_prerelease.append((1, part))

        return (major, minor, patch), processed_prerelease

    v1_core, v1_pre = parse_version(a)
    v2_core, v2_pre = parse_version(b)

    # 1. Compare Major, Minor, Patch
    if v1_core < v2_core:
        return -1
    if v1_core > v2_core:
        return 1

    # 2. Handle Pre-release precedence
    # A version WITH pre-release sorts BEFORE a version WITHOUT
    if v1_pre is not None and v2_pre is None:
        return -1
    if v1_pre is None and v2_pre is not None:
        return 1
    if v1_pre is None and v2_pre is None:
        return 0

    # 3. Compare Pre-release identifiers
    for p1, p2 in zip(v1_pre, v2_pre):
        # p1/p2 are tuples: (type_priority, value)
        # type_priority 0 for numeric, 1 for alphanumeric
        if p1 < p2:
            return -1
        if p1 > p2:
            return 1

    # 4. If all identifiers equal, the one with more parts wins (longer list is "greater")
    # Wait, SemVer spec says: "A larger set of pre-release identifiers has higher precedence"
    # Actually, if prefixes are equal, the longer list is greater.
    if len(v1_pre) < len(v2_pre):
        return -1
    if len(v1_pre) > len(v2_pre):
        return 1

    return 0
