import re

def parse_range(header, size):
    if not header:
        return None

    ranges = []
    # Split by comma and strip whitespace
    parts = [p.strip() for p in header.split(',')]

    for part in parts:
        if not part.startswith('bytes='):
            return None

        range_val = part[6:].strip()
        if not range_val:
            return None

        # Match patterns: 0-499, 500-, -500, or -500-1000 (though RFC says suffix is single value)
        # Pattern 1: start-end (e.g., 0-499)
        # Pattern 2: start- (e.g., 500-)
        # Pattern 3: -suffix (e.g., -500)

        match = re.match(r'^(-?\d*)-?(\d*)?$', range_val)
        if not match:
            return None

        start_str, end_str = match.groups()

        try:
            if start_str == '' and end_str == '':
                # This case shouldn't happen with valid RFC syntax but for safety:
                return None

            if start_str == '' and end_str:
                # Suffix length mode: -500 (last 500 bytes)
                suffix = int(end_str)
                if suffix <= 0:
                    continue
                start = max(0, size - suffix)
                end = size - 1
            elif end_str == '' and start_str:
                # Start- mode: 500- (from 500 to end)
                start = int(start_str)
                end = size - 1
            elif start_str and end_str:
                # Range mode: 0-499
                start = int(start_str)
                end = int(end_str)
            else:
                return None

            # Clamp end to resource size
            end = min(end, size - 1)

            # Check if range is satisfiable
            if start < size and start <= end:
                ranges.append((start, end))
        except ValueError:
            return None

    return ranges if ranges else None
