from decimal import Decimal, ROUND_HALF_EVEN

def round_money(amount: Decimal, places: int) -> Decimal:
    """
    Rounds a decimal.Decimal to 'places' decimal digits using banker's rounding.
    Returns a Decimal quantized to exactly that many places.
    """
    if places < 0:
        raise ValueError("Places must be a non-negative integer.")

    # Create the quantization pattern (e.g., '0.01' for 2 places)
    if places == 0:
        exponent = Decimal('1')
    else:
        exponent = Decimal('1').scaleb(-places)

    return amount.quantize(exponent, rounding=ROUND_HALF_EVEN)
