def next_fire(expr, after):
    parts = expr.split()
    if len(parts) != 5:
        raise ValueError("Invalid cron expression length")

    fields_spec = [
        (0, 59),  # minute
        (0, 23),  # hour
        (1, 31),  # day of month
        (1, 12),  # month
        (0, 6)    # day of week
    ]

    parsed_fields = []

    def parse_part(part, min_val, max_val):
        values = set()
        for item in part.split(','):
            if not item: continue

            # Handle step (e.g., */5 or 1-10/2)
            step = 1
            range_part = item
            if '/' in item:
                range_part, step_str = item.split('/')
                try:
                    step = int(step_str)
                except ValueError:
                    raise ValueError("Invalid step")
                if step <= 0: raise ValueError("Step must be positive")

            # Handle range or single value
            sub_values = []
            if range_part == '*':
                sub_values = list(range(min_val, max_val + 1))
            elif '-' in range_part:
                try:
                    start_str, end_str = range_part.split('-')
                    start, end = int(start_str), int(end_str)
                    if not (min_val <= start <= max_val and min_val <= end <= max_val):
                        raise ValueError("Range out of bounds")
                    sub_values = list(range(start, end + 1))
                except ValueError:
                    raise ValueError("Invalid range format")
            else:
                try:
                    val = int(range_part)
                    if not (min_val <= val <= max_val):
                        raise ValueError("Value out of bounds")
                    sub_values = [val]
                except ValueError:
                    raise ValueError("Invalid value")

            for v in sub_values:
                if (v - min_val) % step == 0:
                    values.add(v)
        return values

    try:
        for i, part in enumerate(parts):
            min_v, max_v = fields_spec[i]
            parsed_fields.append(parse_part(part, min_v, max_v))
    except Exception as e:
        raise ValueError(f"Malformed expression: {e}")

    # Check if day-of-month and day-of-week are both restricted
    dom_restricted = len(parsed_fields[2]) < (31 if 31 in range(0,32) else 0) # Logic check below
    # Correct logic: A field is "restricted" if it's not just '*' (all values)
    # But the prompt says "neither is *". In cron terms, this means both sets are subsets of their full range.
    # However, standard interpretation for "not *" in this context usually means "contains specific constraints".
    # Let's check if the set contains all possible values for that field.

    dom_all = set(range(1, 32))
    dow_all = set(range(0, 7))

    dom_is_star = parsed_fields[2] == dom_all
    dow_is_star = parsed_fields[4] == dow_all

    # We iterate through time. Since we need the NEXT strictly after, 
    # we start from 'after' + 1 second.
    current = datetime.datetime(after.year, after.month, after.day, after.hour, after.minute, after.second, 0)
    if current <= after:
        current += datetime.timedelta(seconds=1)

    # To avoid infinite loops in a real scenario, we'd limit the search, 
    # but for a standard cron utility, we increment.
    # We use a brute-force approach with smart increments.

    while True:
        # Check month/year first (most coarse)
        if current.month not in parsed_fields[3]:
            current = datetime.datetime(current.year, current.month, 1, 0, 0, 0) + datetime.timedelta(days=32)
            continue

        # Check day-of-month and day-of-week logic
        dom_match = current.day in parsed_fields[2]
        dow_match = current.weekday() in parsed_fields[4]

        day_valid = False
        if not dom_is_star and not dow_is_star:
            # Both restricted: match EITHER
            day_valid = dom_match or dow_match
        else:
            # One or both are '*' (unrestricted): match the restricted one
            # If DOM is *, only DOW matters. If DOW is *, only DOM matters. 
            # If both are *, both matter (which is always true).
            day_valid = dom_match and dow_match

        if day_valid:
            # Check hour/minute
            if current.hour in parsed_fields[1] and current.minute in parsed_fields[0]:
                return current

            # If time within the day doesn't match, try next minute of same day
            if current.minute in parsed_fields[0]:
                # Try next hour if possible
                if current.hour < 23:
                    next_check = current.replace(hour=current.hour + 1, minute=0, second=0)
                else:
                    next_check = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0)
                current = next_check
            else:
                # Try next hour
                if current.hour < 23:
                    current = current.replace(hour=current.hour + 1, minute=0, second=0)
                else:
                    current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0)
        else:
            # Day doesn't match, move to next day
            current = (current + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0)

        # Safety break for extreme dates (not required by prompt but good practice)
        if current.year > after.year + 10:
            raise ValueError("No match found in reasonable timeframe")
