def evaluate(expr):
    # Tokenize the expression
    tokens = []
    # Regex for numbers (int/float), operators, and parentheses
    token_pattern = re.compile(r'\d*\.\d+|\d+|[\+\-\*\/\%\(\)\*\*]')

    # Pre-process to handle ** as a single token
    expr = expr.replace('**', ' __POW__ ')
    expr = expr.replace('+', ' + ')
    expr = expr.replace('-', ' - ')
    expr = expr.replace('*', ' * ')
    expr = expr.replace('/', ' / ')
    expr = expr.replace('%', ' % ')
    expr = expr.replace('(', ' ( ')
    expr = expr.replace(')', ' ) ')

    raw_tokens = expr.split()
    for t in raw_tokens:
        if t == '__POW__':
            tokens.append('**')
        else:
            tokens.append(t)

    def get_precedence(op, is_unary):
        if is_unary: return 4
        if op == '**': return 3
        if op in ('*', '/', '%'): return 2
        if op in ('+', '-'): return 1
        return 0

    def apply_op(ops, values):
        if not ops: return
        op = ops.pop()
        if op == 'u-':
            if not values: raise ValueError("Malformed expression")
            values.append(-values.pop())
            return
        if op == 'u+':
            return

        if len(values) < 2: raise ValueError("Malformed expression")
        right = values.pop()
        left = values.pop()

        try:
            if op == '+': values.append(left + right)
            elif op == '-': values.append(left - right)
            elif op == '*': values.append(left * right)
            elif op == '/': values.append(left / right)
            elif op == '%': values.append(left % right)
            elif op == '**': values.append(left ** right)
        except ZeroDivisionError:
            raise ValueError("Division by zero")
        except OverflowError:
            raise ValueError("Result too large")
        except Exception:
            raise ValueError("Malformed expression")

    values = []
    ops = []
    i = 0

    while i < len(tokens):
        token = tokens[i]

        # Check if token is a number
        try:
            val = float(token)
