            values.append(val)
        except ValueError:
            # Handle operators
            if token == '(':
                ops.append('(')
            elif token == ')':
                while ops and ops[-1] != '(':
                    apply_op(ops, values)
                if not ops: raise ValueError("Mismatched parentheses")
                ops.pop() # pop '('
            elif token in ('+', '-', '*', '/', '%', '**'):
                # Check for unary minus/plus
