class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.num_sets = n
        self.history = []

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        root_a = self.find(a)
        root_b = self.find(b)
        if root_a == root_b:
            return False

        # Union by size
        if self.size[root_a] < self.size[root_b]:
            root_a, root_b = root_b, root_a

        # Record changes for rollback: (child, parent, old_parent_size, old_num_sets)
        self.history.append((root_b, root_a, self.size[root_a], self.num_sets))

        self.parent[root_b] = root_a
        self.size[root_a] += self.size[root_b]
        self.num_sets -= 1
        return True

    def snapshot(self):
        # The token is simply the current length of the history stack
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            child, parent, old_parent_size, old_num_sets = self.history.pop()
            self.parent[child] = child
            self.size[parent] = old_parent_size
            self.num_sets = old_num_sets

    def components(self):
        return self.num_sets
