        if not intervals:
            return []
        sorted_intervals = sorted(intervals, key=lambda x: x[0])
        merged = []
        for start, end in sorted_intervals:
            if start >= end:
                continue
            if not merged or start > merged[-1][1]:
                merged.append([start, end])
            else:
                merged[-1][1] = max(merged[-1][1], end)
        return merged

    # 1. Normalize base and cuts by merging overlapping intervals within each list
    base_merged = merge_intervals(base)
    cuts_merged = merge_intervals(cuts)

    if not base_merged:
        return []
    if not cuts_merged:
        return base_merged

    result = []
    for b_start, b_end in base_merged:
        current_start = b_start

        # 2. For each base interval, subtract all overlapping cut intervals
        for c_start, c_end in cuts_merged:
            # If the cut is completely after the current base segment, no more cuts matter for this segment
            if c_start >= b_end:
                break
            # If the cut is completely before the current base segment, skip it
            if c_end <= current_start:
                continue

            # If there is a gap between the current start and the beginning of the cut
            if c_start > current_start:
                result.append([current_start, c_start])

            # Move the pointer to the end of the cut
            current_start = max(current_start, c_end)

            # If we've moved past the end of the base interval, stop checking cuts
            if current_start >= b_end:
                break

        # 3. Add the remaining part of the base interval if it exists
        if current_start < b_end:
            result.append([current_start, b_end])

    # 4. Final pass to merge any adjacent intervals that might have been created
    return merge_intervals(result)
