def deep_copy(obj, memo=None):
    if memo is None:
        memo = {}

    # Return scalars as-is (immutable and don't need tracking)
    if isinstance(obj, (str, int, float, bool, type(None))):
        return obj

    # Check if we have already copied this object to preserve sharing/cycles
    if id(obj) in memo:
        return memo[id(obj)]

    if isinstance(obj, list):
        new_list = []
        memo[id(obj)] = new_list
        for item in obj:
            new_list.append(deep_copy(item, memo))
        return new_list

    elif isinstance(obj, tuple):
        # Tuples are immutable, but can contain mutable objects.
        # We must reconstruct the tuple with deep-copied elements.
        # Note: The tuple itself cannot be modified after creation, 
        # so we compute elements first then add to memo.
        temp_elements = []
        for item in obj:
            temp_elements.append(deep_copy(item, memo))
        new_tuple = tuple(temp_elements)
        memo[id(obj)] = new_tuple
        return new_tuple

    elif isinstance(obj, set):
        new_set = set()
        memo[id(obj)] = new_set
        for item in obj:
            new_set.add(deep_copy(item, memo))
        return new_set

    elif isinstance(obj, dict):
        new_dict = {}
        memo[id(obj)] = new_dict
        for key, value in obj.items():
            # Keys can also be complex objects (like tuples)
            new_key = deep_copy(key, memo)
            new_dict[new_key] = deep_copy(value, memo)
        return new_dict

    else:
        # Fallback for any other types not specified in the prompt
        return obj
