import heapq
from collections import deque, defaultdict

def topo_lex(graph):
    # Step 1: Identify all nodes in the graph
    # Nodes can be keys (predecessors) or values (successors)
    all_nodes = set(graph.keys())
    for successors in graph.values():
        for node in successors:
            all_nodes.add(node)

    # Step 2: Build adjacency list and calculate in-degrees
    # The input 'graph' maps node -> nodes that depend on it (successors)
    # This is already the adjacency list for a standard topological sort
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for u, successors in graph.items():
        for v in successors:
            adj[u].append(v)
            in_degree[v] += 1

    # Step 3: Initialize Min-Heap with nodes having in-degree 0
    # Using a heap ensures we always pick the lexicographically smallest node
    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    topo_order = []

    # Step 4: Kahn's Algorithm
    while heap:
        u = heapq.heappop(heap)
        topo_order.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    # Step 5: Check for cycles
    # If topo_order doesn't contain all nodes, there is a cycle
    if len(topo_order) == len(all_nodes):
        return topo_order
    else:
        return None
