const deepEqual = (a, b, visited = new WeakMap()) => {
  // SameValueZero: NaN === NaN, +0 === -0
  if (Object.is(a, b) || (Number.isNaN(a) && Number.isNaN(b))) {
    return true;
  }

  if (typeof a !== 'object' || a === null || typeof b !== 'object' || b === null) {
    return false;
  }

  // Handle circular references
  if (visited.has(a) && visited.get(a) === b) {
    return true;
  }
  visited.set(a, b);

  const protoA = Object.getPrototypeOf(a);
  const protoB = Object.getPrototypeOf(b);

  if (protoA !== protoB) {
    return false;
  }

  // Date comparison
  if (a instanceof Date) {
    return a.getTime() === b.getTime();
  }

  // RegExp comparison
  if (a instanceof RegExp) {
    return a.source === b.source && a.flags === b.flags;
  }

  // Set comparison
  if (a instanceof Set) {
    if (a.size !== b.size) return false;
    for (const val of a) {
      let found = false;
      for (const bVal of b) {
        if (deepEqual(val, bVal, visited)) {
          found = true;
          break;
        }
      }
      if (!found) return false;
    }
    return true;
  }

  // Map comparison
  if (a instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [keyA, valA] of a) {
      let foundMatch = false;
      for (const [keyB, valB] of b) {
        if (deepEqual(keyA, keyB, visited) && deepEqual(valA, valB, visited)) {
          foundMatch = true;
          break;
        }
      }
      if (!foundMatch) return false;
    }
    return true;
  }

  // Array and Plain Object comparison
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);

  if (keysA.length !== keysB.length) {
    return false;
  }

  for (const key of keysA) {
    if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key], visited)) {
      return false;
    }
  }

  return true;
