module.exports = function pLimit(n) {
  let activeCount = 0;
  const queue = [];

  const next = () => {
    if (queue.length === 0 || activeCount >= n) {
      return;
    }

    activeCount++;
    const { task, resolve, reject } = queue.shift();

    task()
      .then(resolve)
      .catch(reject)
      .finally(() => {
        activeCount--;
        next();
      });

    next();
  };

  return (task) => {
    return new Promise((resolve, reject) => {
      queue.push({ task, resolve, reject });
      next();
    });
  };
};
