class Emitter {
  constructor() {
    this._listeners = new Map();
  }

  on(event, fn) {
    if (!this._listeners.has(event)) {
      this._listeners.set(event, []);
    }
    const list = this._listeners.get(event);
    list.push(fn);

    return () => this.off(event, fn);
  }

  once(event, fn) {
    const wrapper = (...args) => {
      this.off(event, wrapper);
      fn(...args);
    };
    return this.on(event, wrapper);
  }

  off(event, fn) {
    const list = this._listeners.get(event);
    if (!list) return;
    const index = list.indexOf(fn);
    if (index !== -1) {
      list.splice(index, 1);
    }
  }

  emit(event, ...args) {
    const list = this._listeners.get(event);
    if (!list || list.length === 0) return 0;

    // Snapshot the current listeners to ensure:
    // 1. Listeners added during emit are not invoked in this cycle.
    // 2. Listeners removed during emit are not invoked in this cycle.
    const snapshot = [...list];
    let invokedCount = 0;
    let firstError = null;

    for (const listener of snapshot) {
      // Check if the listener was removed from the original list during the loop
      if (!list.includes(listener)) {
        continue;
      }

      try {
        listener(...args);
        invokedCount++;
      } catch (err) {
        if (!firstError) {
          firstError = err;
        }
      }
    }

    if (firstError) {
      throw firstError;
    }

    return invokedCount;
  }
}

module.exports = Emitter;
