module.exports = function singleFlight(loader) {
  const inflightMap = new Map();

  const load = function(key) {
    if (inflightMap.has(key)) {
      return inflightMap.get(key);
    }

    const promise = loader(key).finally(() => {
      inflightMap.delete(key);
    });

    inflightMap.set(key, promise);
    return promise;
  };

  Object.defineProperty(load, 'inflight', {
    get: () => inflightMap.size,
    enumerable: true,
    configurable: false
  });

  return load;
};
