module.exports = function zipLongest(fill, ...iterables) {
  if (iterables.length === 0) return;

  const iterators = iterables.map(it => {
    const iterator = typeof it[Symbol.iterator] === 'function' ? it[Symbol.iterator]() : it;
    return {
      iterator,
      done: false,
      nextValue: undefined
    };
  });

  // Pre-fetch the first value for each to establish initial state
  for (const entry of iterators) {
    const result = entry.iterator.next();
    if (result.done) {
      entry.done = true;
    } else {
      entry.nextValue = result.value;
    }
  }

  function* generator() {
    while (true) {
      let allDone = true;
      const row = [];

      for (const entry of iterators) {
        if (entry.done) {
          row.push(fill);
        } else {
          row.push(entry.nextValue);
          allDone = false;
          // Pull exactly one item for the next iteration
          const result = entry.iterator.next();
          if (result.done) {
            entry.done = true;
          } else {
            entry.nextValue = result.value;
          }
        }
      }

      if (allDone) break;
      yield row;
    }
  }

  return generator();
