function createStore(reducer, initial) {
  let state = initial;
  let isDispatching = false;
  let isNotifying = false;
  let subscribers = [];

  return {
    getState: () => state,
    dispatch: (action) => {
      if (isDispatching) {
        throw new Error('Reducers may not dispatch actions.');
      }

      isDispatching = true;
      try {
        state = reducer(state, action);
      } finally {
        isDispatching = false;
      }

      if (isNotifying) {
        return;
      }

      isNotifying = true;
      try {
        const currentSubscribers = subscribers;
        for (let i = 0; i < currentSubscribers.length; i++) {
          currentSubscribers[i]();
        }
      } finally {
        isNotifying = false;
      }
    },
    subscribe: (fn) => {
      let isSubscribed = true;
      subscribers.push(() => {
        if (isSubscribed) {
          fn();
        }
      });

      return () => {
        isSubscribed = false;
      };
    }
  };
}

module.exports = createStore;
