module.exports = {
  toposortTasks: async (tasks) => {
    const results = {};
    const promises = {};
    const running = new Set();

    // Check for missing dependencies and cycles using DFS
    const visited = new Set();
    const recStack = new Set();

    function detectCycle(node) {
      if (recStack.has(node)) return true;
      if (visited.has(node)) return false;

      visited.add(node);
      recStack.add(node);

      const task = tasks[node];
      if (!task) {
        throw new Error(`Unknown dependency: ${node}`);
      }

      for (const dep of task.deps) {
        if (detectCycle(dep)) return true;
      }

      recStack.delete(node);
      return false;
    }

    for (const name in tasks) {
      if (detectCycle(name)) {
        throw new Error("Dependency cycle detected");
      }
    }

    const executeTask = async (name) => {
      const task = tasks[name];

      // Wait for all dependencies to resolve
      const depPromises = task.deps.map(dep => promises[dep]);
      await Promise.all(depPromises);

      // Construct the dependency values object
      const depValues = {};
      for (const dep of task.deps) {
        depValues[dep] = results[dep];
      }

      // Run the actual task
      const value = await task.run(depValues);
      results[name] = value;
      return value;
    };

    // Initialize all promises immediately to allow concurrency
    for (const name in tasks) {
      promises[name] = executeTask(name);
    }

    // Wait for all top-level task chains to complete
    // Note: If one fails, Promise.all will reject, but other 
    // independent branches continue running in the background.
    await Promise.all(Object.values(promises));

    return results;
  }
};
