export class Bus<E extends Record<string, unknown>> {
  private handlers: { [K in keyof E]?: Array<(payload: E[K]) => void> } = {};

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.handlers[k]) {
      this.handlers[k] = [];
    }
    this.handlers[k]!.push(fn);

    return () => {
      const listeners = this.handlers[k];
      if (listeners) {
        this.handlers[k] = listeners.filter((h) => h !== fn);
      }
    };
  }

  emit<K extends keyof E>(
    k: K,
    ...args: E[K] extends void ? [] : [payload: E[K]]
  ): void {
    const payload = args[0];
    const listeners = this.handlers[k];
    if (listeners) {
      for (const fn of listeners) {
        fn(payload as E[K]);
      }
    }
  }
}
