 * This utility type extracts the handlers object structure from a union.
 * It maps each 'kind' property to a function that accepts the specific subtype.
 */
type MatchHandlers<T, R> = {
  [K in keyof T]: (value: Extract<T, { kind: T[K] }>) => R;
};

/**
 * The match function performs exhaustive pattern matching.
 * 
 * @param value - The discriminated union instance to match against.
 * @param handlers - An object containing a handler for every possible 'kind' in the union.
 * @returns The result of the executed handler.
 */
export function match<T extends { kind: string }, R>(
  value: T,
  handlers: {
    [K in keyof T]: (value: Extract<T, { kind: T[K] }>) => R;
  } & {
