    // from handlers, it results in a type error.
    [P in keyof T]: never extends any ? never : never;
  }
): R {
  const handler = handlers[value.kind as keyof typeof handlers];
  if (!handler) {
    throw new Error(`Unhandled variant: ${value.kind}`);
  }
  return handler(value as any);
}

