  ? DeepAwaited<U>
  : T extends Array<infer U>
  ? Array<DeepAwaited<U>>
  : T extends object
  ? { [K in keyof T]: DeepAwaited<T[K]> }
  : T;

export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (value instanceof Promise) {
    const resolved = await value;
    return deepAwait(resolved) as any;
  }

  if (Array.isArray(value)) {
    return Promise.all(value.map((item) => deepAwait(item))) as any;
  }

  if (value !== null && typeof value === 'object' && typeof (value as any).then !== 'function') {
    const result = {} as any;
    const keys = Object.keys(value) as Array<keyof T>;
    await Promise.all(
      keys.map(async (key) => {
        result[key] = await deepAwait((value as any)[key]);
      })
    );
    return result as any;
  }

  return value as any;
}
