export function pick<T extends object, K extends keyof T>(
  obj: T,
  keys: K[]
): Pick<T, Extract<K, keyof T>> {
  const result = {} as Pick<T, Extract<K, keyof T>>;
  for (const key of keys) {
    if (Object.prototype.hasOwnPropertyCall(obj, key)) {
      (result as any)[key] = (obj as any)[key];
    }
  }
  return result;
}

export function omit<T extends object>(
  obj: T,
  keys: Array<keyof T>
): Omit<T, keyof T> {
  const result = {} as Omit<T, keyof T>;
  const targetKeys = new Set(keys);
  for (const key in obj) {
    if (
      Object.prototype.hasOwnPropertyCall(obj, key) &&
      !targetKeys.has(key as keyof T)
    ) {
      (result as any)[key] = (obj as any)[key];
    }
  }
  return result;
}
