export type Result<T, E> = Ok<T, E> | Err<T, E>;

export class Ok<T, E> {
  readonly tag = 'ok' as const;
  constructor(readonly value: T) {}
}

export class Err<T, E> {
  readonly tag = 'err' as const;
  constructor(readonly error: E) {}
}

export const ok = <T, E>(value: T): Result<T, E> => new Ok(value);
export const err = <T, E>(error: E): Result<T, E> => new Err(error);

export function isOk<T, E>(result: Result<T, E>): result is Ok<T, E> {
  return result.tag === 'ok';
}

export function isErr<T, E>(result: Result<T, E>): result is Err<T, E> {
  return result.tag === 'err';
}

export function map<T, E, U>(
  result: Result<T, E>,
  fn: (value: T) => U
): Result<U, E> {
  if (isOk(result)) {
    return ok(fn(result.value));
  }
  return err(result.error);
}

export function unwrapOr<T, E>(result: Result<T, E>, defaultValue: T): T {
  if (isOk(result)) {
    return result.value;
  }
  return defaultValue;
}
