type PathTemplate = string;

type ExtractParams<T extends string> =
  T extends `${infer _Start}:${infer Param}/${infer Rest}`
    ? { [K in Lowercase<Param & string>]: string } & ExtractParams<`/${Rest}`>
    : T extends `${infer _Start}:${infer Param}`
      ? { [K in Lowercase<Param & string>]: string }
      : {};

type RouteMap = Record<string, PathTemplate>;

type GeneratedRoutes<T extends RouteMap> = {
  [K in keyof T as K]: (params: ExtractParams<T[K]>) => string;
};

// Overload for paths with no params to allow zero-argument calls
type FinalRoutes<T extends RouteMap> = {
  [K in keyof T]: ExtractParams<T[K]> extends Record<string, never>
    ? () => string
    : (params: ExtractParams<T[K]>) => string;
};

export function defineRoutes<T extends RouteMap>(routes: T): FinalRoutes<T> {
  const result = {} as any;

  for (const [name, template] of Object.entries(routes)) {
    result[name] = (...args: any[]) => {
      let path = template;
      const params: Record<string, string | undefined> = {};

      // Map args to named segments in order
      const paramNames: string[] = [];
      const regex = /:([a-zA-Z0-9_]+)/g;
      let match;
      while ((match = regex.exec(template)) !== null) {
        paramNames.push(match[1]);
      }

      paramNames.forEach((p, index) => {
        params[p] = args[index];
      });

      // Replace :name with value from params object
      return template.replace(/:([a-zA-Z0-9_]+)/g, (_, key) => {
        const val = params[key];
        if (val === undefined) throw new Error(`Missing param: ${key}`);
        return val;
      });
    };
  }

  return result as FinalRoutes<T>;
}
