export type DeepPartial<T>
  = T extends object
    ? {
        [P in keyof T]?: DeepPartial<T[P]>;
      }
    : T;

/**
 * Merges patch into base recursively.
 * - Returns a new object (immutability).
 * - Arrays are replaced wholesale.
 * - Functions are treated as primitives (replaced if present).
 * - undefined in patch means "leave alone".
 */
export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  // If patch is undefined, return base as per "leave alone" rule
  if (patch === undefined) {
    return base;
  }

  // If patch is not an object or is null, it's a primitive replacement
  if (typeof patch !== 'object' || patch === null) {
    return patch as T;
  }

  // If base is not an object/array, the patch (which is an object) replaces it
  if (typeof base !== 'object' || base === null) {
    return JSON.parse(JSON.stringify(patch));
  }

  // Handle Arrays: Replace wholesale
  if (Array.isArray(patch)) {
    return JSON.parse(JSON.stringify(patch)) as T;
  }

  // Handle Objects
  const result = Array.isArray(base) ? [] : { ...base };

  for (const key in patch) {
    if (Object.prototype.hasOwnProperty.call(patch, key)) {
      const patchValue = (patch as any)[key];
      const baseValue = (base as any)[key];

      if (patchValue !== undefined) {
        result[key] = applyPatch(baseValue, patchValue);
      }
    }
  }

  return result as T;
}
